import {routePieces,flattenParts} from './hybrid-core.js?v=24';
const MAX_POINTS=15000;
export const isSea=r=>r.kind==='sea'||r.group==='searoutes';
export const lengthOf=points=>points.slice(1).reduce((s,p,i)=>s+Math.hypot(p[0]-points[i][0],p[1]-points[i][1]),0);
export function simplify(points,tolerance=5){if(points.length<3)return points.map(p=>p.slice(0,2));const a=points[0],b=points.at(-1),dx=b[0]-a[0],dy=b[1]-a[1],den=dx*dx+dy*dy;let best=tolerance,index=-1;for(let i=1;i<points.length-1;i++){const p=points[i],t=den?Math.max(0,Math.min(1,((p[0]-a[0])*dx+(p[1]-a[1])*dy)/den)):0,d=Math.hypot(p[0]-a[0]-t*dx,p[1]-a[1]-t*dy);if(d>best){best=d;index=i;}}return index<0?[a.slice(0,2),b.slice(0,2)]:[...simplify(points.slice(0,index+1),tolerance).slice(0,-1),...simplify(points.slice(index),tolerance)];}
export function normalizeRoute(r,index=0){const points=r.points.map(p=>p.slice(0,2));return {...r,id:String(r.id??'land-'+(r.i??index)),name:String(r.name||'Estrada '+(index+1)).slice(0,150),kind:r.kind==='mixed'?'mixed':isSea(r)?'sea':'road',group:isSea(r)?'searoutes':r.group||'roads',majorRoute:r.majorRoute!==false,enabled:r.enabled!==false,points,controls:(r.controls||simplify(points)).map(p=>p.slice(0,2))};}
export function cleanNetwork(raw,D){if(raw?.format!=='silvengard-network-v1'||!(raw.baseVersion===(D.networkDefaults?.version??13)||D.networkDefaults?.version===13&&raw.baseVersion===12)||!Array.isArray(raw.routes)||raw.routes.length>500||!Array.isArray(raw.deleted)||raw.deleted.length>500)throw Error('Arquivo de rotas inválido ou de outra versão');const used=new Set(),valid=p=>Array.isArray(p)&&p.length>=2&&p.slice(0,2).every(Number.isFinite)&&p[0]>=0&&p[0]<=1920&&p[1]>=0&&p[1]<=937;const routes=raw.routes.filter(r=>!D.citySelection?.removedRouteIds?.includes(r.id)).map((r,i)=>{if(typeof r.id!=='string'||r.id.length>100||used.has(r.id)||!Array.isArray(r.points)||r.points.length<2||r.points.length>MAX_POINTS||!r.points.every(valid)||!Array.isArray(r.controls)||r.controls.length<2||r.controls.length>200||!r.controls.every(valid)||!['road','sea','mixed'].includes(r.kind))throw Error('Traçado inválido');used.add(r.id);let parts;if(r.kind==='mixed'){if(!Array.isArray(r.parts)||!r.parts.length||r.parts.length>500)throw Error('Trechos híbridos inválidos');parts=r.parts.map(p=>{if(!['road','sea'].includes(p.kind)||!Array.isArray(p.points)||p.points.length<2||p.points.length>MAX_POINTS||!p.points.every(valid))throw Error('Trecho híbrido inválido');return {kind:p.kind,points:p.points.map(p=>p.slice(0,2))};});if(JSON.stringify(flattenParts(parts))!==JSON.stringify(r.points.map(p=>p.slice(0,2))))throw Error('Os trechos híbridos não correspondem à rota');}return normalizeRoute({id:r.id,name:String(r.name||'Rota').slice(0,150),kind:r.kind,stopMode:r.stopMode==='explicit'?'explicit':undefined,tradeUse:r.tradeUse!==false,routeClass:r.routeClass,...(parts?{parts}:{}),majorRoute:raw.baseVersion===12&&/^(land-|sea-)/.test(r.id)?false:r.majorRoute!==false,stops:Array.isArray(r.stops)?r.stops.filter(i=>Number.isInteger(i)&&D.cities.some(b=>b.i===i)).slice(0,100):[],enabled:r.enabled!==false,points:r.points,controls:r.controls,stateIds:Array.isArray(r.stateIds)?r.stateIds.filter(v=>Number.isInteger(v)&&D.states.some(s=>s.i===v)):[],fromCity:D.cities.some(b=>b.i===r.fromCity)?r.fromCity:null,toCity:D.cities.some(b=>b.i===r.toCity)?r.toCity:null},i);});return {format:'silvengard-network-v1',baseVersion:D.networkDefaults?.version??13,routes,deleted:raw.deleted.filter(v=>typeof v==='string'&&v.length<=100)};}
export function createNetworkModel(D){const base=D.routes.map(normalizeRoute);D.routes=structuredClone(base);const undo=[],redo=[];function snapshot(){return structuredClone(D.routes);}function commit(next){undo.push(snapshot());if(undo.length>40)undo.shift();redo.length=0;D.routes=next;}return {replaceAll(routes){commit(routes.map(normalizeRoute));},save(route){const next=snapshot(),i=next.findIndex(r=>r.id===route.id);if(i<0)next.push(normalizeRoute(route,next.length));else next[i]=normalizeRoute(route,i);commit(next);},remove(id){commit(snapshot().filter(r=>r.id!==id));},undo(){if(!undo.length)return false;redo.push(snapshot());D.routes=undo.pop();return true;},redo(){if(!redo.length)return false;undo.push(snapshot());D.routes=redo.pop();return true;},exportData(){return {format:'silvengard-network-v1',baseVersion:D.networkDefaults?.version??13,routes:D.routes.filter(r=>JSON.stringify(r)!==JSON.stringify(base.find(b=>b.id===r.id))),deleted:base.filter(b=>!D.routes.some(r=>r.id===b.id)).map(r=>r.id)};},importData(raw){const clean=cleanNetwork(raw,D),over=new Map(clean.routes.map(r=>[r.id,r])),deleted=new Set(clean.deleted),next=base.filter(r=>!deleted.has(r.id)).map(r=>structuredClone(over.get(r.id)||r));for(const r of clean.routes)if(!next.some(n=>n.id===r.id))next.push(r);commit(next);},get canUndo(){return !!undo.length;},get canRedo(){return !!redo.length;}};}
export function buildNetworkIndex(D){const g=D.grid,nearest=p=>D.cells[Math.max(0,Math.min(g.rows-1,Math.floor(p[1]/g.stepY)))*g.columns+Math.max(0,Math.min(g.columns-1,Math.floor(p[0]/g.stepX)))],road=new Uint8Array(D.cells.length),sea=new Uint8Array(D.cells.length),portEdges=new Map();
 for(const route of D.routes||[]){if(route.enabled===false)continue;for(const r of routePieces(route)){if(r.points.length<2)continue;const isWater=r.kind==='sea',mask=isWater?sea:road;for(let i=1;i<r.points.length;i++){const a=r.points[i-1],b=r.points[i],steps=Math.max(1,Math.ceil(Math.hypot(b[0]-a[0],b[1]-a[1])/Math.min(g.stepX,g.stepY)*3));for(let k=0;k<=steps;k++){const t=k/steps,c=nearest([a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t]);if((c.h<20)===isWater)mask[c.i]=1;}}}}

 const lanes=sea.slice();for(let i=0;i<lanes.length;i++)if(lanes[i])for(const j of D.cells[i].c)if(D.cells[j].h<20)sea[j]=1;
 for(const b of D.cities||[]){if(!b.harbor||!sea[b.harbor.cell])continue;const land=b.cell,water=b.harbor.cell;if(D.cells[land]?.h<20)continue;const distance=Math.hypot(...D.cells[land].p.map((v,i)=>v-D.cells[water].p[i]));for(const [a,z]of [[land,water],[water,land]]){if(!portEdges.has(a))portEdges.set(a,[]);portEdges.get(a).push({id:z,distance});}}
 return {road,sea,portEdges,nearest};
}
